#!/usr/bin/env bash
# Some portions generated by Codex. Fixed four paired blocks; independent server restarts.
set -euo pipefail
cd "$(dirname "$0")/../../.."
i=0
for arm in base depth depth base base depth depth base; do
 i=$((i+1))
 python3 experiments/threadlocal-audit/depth-workbench/run.py "$arm" "matched-$(printf '%02d' "$i")-$arm" --warmups 20 --iterations 10
done
